style.css:
/* AQUA DREAMSCAPE — Global */

:root {
  /* Change these colors if you want */
  --my-turquoise: #20cfc5;
  --my-deep-aqua: #079f9e;
  --my-light-aqua: #a4fff5;
  --my-white: #ffffff;
  --my-glass: rgba(255, 255, 255, 0.19);
  --my-glow: rgba(255, 255, 255, 0.42);
}

/* main background */
html,
body {
  background:
    radial-gradient(ellipse at 15% 10%, #a8fff4 0%, transparent 38%),
    radial-gradient(ellipse at 85% 85%, #00aeb3 0%, transparent 45%),
    linear-gradient(135deg, #43e5d5, #13bdbb 48%, #087f91) !important;
  background-attachment: fixed !important;
  color: var(--my-white) !important;
}

/* white typography */
h1, h2, h3, h4, h5, h6,
p, span, label, li {
  color: var(--my-white) !important;
}

/* glossy links */
a {
  color: #ffffff !important;
  text-decoration-color: rgba(255,255,255,.6) !important;
  transition: all .25s ease !important;
}

a:hover {
  text-shadow: 0 0 12px white !important;
}

/* frosted glass surfaces */
header, nav, aside, section, article,
main, [role="navigation"], [role="complementary"] {
  backdrop-filter: blur(18px) saturate(160%) !important;
}

/* glass buttons */
button, [role="button"] {
  background: linear-gradient(
    145deg,
    rgba(255,255,255,.42),
    rgba(255,255,255,.12)
  ) !important;
  color: white !important;
  border: 1px solid rgba(255,255,255,.55) !important;
  border-radius: 14px !important;
  box-shadow:
    0 5px 18px rgba(0,100,110,.16),
    inset 0 1px 2px rgba(255,255,255,.7) !important;
  transition: .25s ease !important;
}

button:hover, [role="button"]:hover {
  transform: translateY(-2px) !important;
  box-shadow: 0 0 22px rgba(255,255,255,.45) !important;
}

/* rounded images */
img, video {
  border-radius: 14px !important;
}

/* elegant scrollbars */
* {
  scrollbar-color: #a4fff5 #078e99;
}

/* selected text */
::selection {
  background: #ffffff !important;
  color: #079f9e !important;
}
